import unittest
from candidate import longest

class TestLongestString(unittest.TestCase):
    def test_longest_empty_list(self):
        self.assertIsNone(longest([]))

    def test_longest_single_element_list(self):
        self.assertEqual(longest(['a']), 'a')

    def test_longest_multiple_elements_list(self):
        self.assertEqual(longest(['a', 'bb', 'ccc']), 'ccc')

    def test_longest_multiple_elements_same_length_list(self):
        self.assertEqual(longest(['aa', 'bb', 'cc']), 'aa')

    def test_longest_list_with_none_element(self):
        self.assertEqual(longest(['a', None, 'ccc']), 'ccc')

    def test_longest_list_with_empty_string(self):
        self.assertEqual(longest(['a', '', 'ccc']), 'ccc')

    def test_longest_list_with_single_empty_string(self):
        self.assertEqual(longest(['']), '')

    def test_longest_list_with_multiple_empty_strings(self):
        self.assertEqual(longest(['', '', '']), '')

    def test_longest_list_with_mixed_types(self):
        with self.assertRaises(TypeError):
            longest(['a', 1, 'ccc'])

    def test_longest_none_input(self):
        with self.assertRaises(TypeError):
            longest(None)

if __name__ == '__main__':
    unittest.main()
